435	func TestCorruptLedgerRejected(t *testing.T) {
436		good := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 1000}})
437		l := openOrFail(t, good)
438		if _, err := l.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{intent("p", "aa", "usdc", 300)}}); err != nil {
439			t.Fatal(err)
440		}
441		if err := l.Close(); err != nil {
442			t.Fatal(err)
443		}
444	
445		dir := filepath.Dir(good)
446		write := func(name string, data []byte) string {
447			p := filepath.Join(dir, name)
448			if err := os.WriteFile(p, data, 0o600); err != nil {
449				t.Fatal(err)
450			}
451			return p
452		}
453		raw, err := os.ReadFile(good)
454		if err != nil {
455			t.Fatal(err)
456		}
457		cases := map[string]string{
458			"garbage":     write("garbage.json", []byte(`garbage{`)),
459			"empty":       write("empty.json", nil),
460			"no checksum": write("nochecksum.json", []byte(`{"version":1,"initial_balances":[],"balances":[],"settlements":[]}`)),
461			"truncated":   write("trunc.json", raw[:len(raw)/2]),
462			"appended":    write("appended.json", append(bytes.Clone(raw), []byte("{}")...)),
463			"bitflip": func() string {
464				b := bytes.Clone(raw)
465				b[12] ^= 0x01
466				return write("bitflip.json", b)
467			}(),
468			"semantic edit": write("edited.json",
469				[]byte(strings.ReplaceAll(string(raw), `"balance":700`, `"balance":999`))),
470		}
471		for name, p := range cases {
472			t.Run(name, func(t *testing.T) {
473				if _, err := Open(p); KindOf(err) != ErrCorrupt {
474					t.Fatalf("%s: want ErrCorrupt, got %v", name, err)
475				}
476			})
477		}
478	
479		// 损坏文件不能通过再次初始化“重开一本空账”。
480		if err := CreateLedger(cases["truncated"], nil); KindOf(err) != ErrExists {
481			t.Fatalf("init over corrupt file must report ErrExists, got %v", err)
482		}
483	}
