491	
492		mk := func(mut func(*Record)) []Record {
493			r := good
494			mut(&r)
495			return []Record{r}
496		}
497	
498		bad := map[string]struct {
499			initial map[balanceKey]int64
500			final   map[balanceKey]int64
501			records []Record
502		}{
503			"seq gap":          {initial, final, mk(func(r *Record) { r.Seq = 2 })},
504			"fee mismatch":     {initial, final, mk(func(r *Record) { r.Fee = 5; r.Charged = 305 })},
505			"charged mismatch": {initial, final, mk(func(r *Record) { r.Charged = 301 })},
506			"bad bps":          {initial, final, mk(func(r *Record) { r.FeeBps = 10001 })},
507			"empty account":    {initial, final, mk(func(r *Record) { r.Account = "" })},
508			"unknown combo":    {initial, final, mk(func(r *Record) { r.Asset = "eth" })},
509			"drives negative":  {initial, map[balanceKey]int64{k: 600}, mk(func(r *Record) {})}, // 扣款 300 但末态写 600
510			"final too high":   {initial, map[balanceKey]int64{k: 800}, mk(func(r *Record) {})},
511		}
512		for name, tc := range bad {
513			t.Run(name, func(t *testing.T) {
514				if err := validateAndReplay(tc.initial, tc.final, tc.records, nil); err == nil || KindOf(err) != ErrCorrupt {
