516				}
517			})
518		}
519	
520		t.Run("duplicate id", func(t *testing.T) {
521			err := validateAndReplay(
522				map[balanceKey]int64{k: 1000},
523				map[balanceKey]int64{k: 400},
524				[]Record{good, func() Record { r := good; r.Seq = 2; return r }()},
525				nil,
526			)
527			if err == nil || KindOf(err) != ErrCorrupt {
528				t.Fatalf("want ErrCorrupt, got %v", err)
529			}
530		})
531	
532		// 健康状态必须通过。
533		if err := validateAndReplay(initial, final, []Record{good}, nil); err != nil {
534			t.Fatalf("healthy state rejected: %v", err)
535		}
